CREATE TYPE "IntentOperation" AS ENUM ('DEPLOY_COLLECTION', 'MINT', 'MINT_BATCH', 'APPROVE', 'SET_APPROVAL_FOR_ALL', 'CREATE_LISTING', 'PURCHASE', 'CANCEL_LISTING', 'WITHDRAW');
CREATE TYPE "IntentStatus" AS ENUM ('CREATED', 'SUBMITTED', 'CONFIRMED', 'FAILED', 'EXPIRED', 'CONSUMED');
CREATE TABLE "TransactionIntent" ("idempotencyKey" VARCHAR(128) NOT NULL, "id" UUID NOT NULL, "walletId" UUID NOT NULL, "operation" "IntentOperation" NOT NULL, "chainId" INTEGER NOT NULL, "requestHash" CHAR(64) NOT NULL, "to" VARCHAR(42) NOT NULL, "data" TEXT NOT NULL, "value" VARCHAR(78) NOT NULL DEFAULT '0', "gas" VARCHAR(78), "status" "IntentStatus" NOT NULL DEFAULT 'CREATED', "expiresAt" TIMESTAMP(3) NOT NULL, "txHash" VARCHAR(66), "failureCode" VARCHAR(64), "failureDetails" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "submittedAt" TIMESTAMP(3), "confirmedAt" TIMESTAMP(3), "failedAt" TIMESTAMP(3), "consumedAt" TIMESTAMP(3), CONSTRAINT "TransactionIntent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TransactionIntent_walletId_idempotencyKey_key" ON "TransactionIntent"("walletId", "idempotencyKey");
CREATE INDEX "TransactionIntent_walletId_status_expiresAt_idx" ON "TransactionIntent"("walletId", "status", "expiresAt");
ALTER TABLE "TransactionIntent" ADD CONSTRAINT "TransactionIntent_walletId_fkey" FOREIGN KEY ("walletId") REFERENCES "WalletProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
